(()=>{const h=window.__wolfTest,p=document.createElement('aside');p.style='position:fixed;right:4px;top:4px;z-index:400;background:#fff;color:#123;padding:6px;max-width:270px';p.innerHTML='<b>困难羊微场景</b><div><button data-flock="detour">已发现可绕行陷阱</button><button data-flock="startle">惊吓中尚未发现</button><button id="readFlock">读取羊决策</button></div><pre id="flockReceipt" style="white-space:pre-wrap"></pre>';document.body.appendChild(p);p.onclick=e=>{const id=e.target.dataset.flock;if(!id)return;h.dismissAllGuides();h.setDifficulty('hard');h.load(11);h.clean();h.start();h.clean();const cells=id==='detour'?[[1,3],[2,3],[3,3],[2,2],[2,1],[3,1]]:[[1,3],[2,3],[3,3]],open=new Set(cells.map(p=>p.join(','))),voids=new Set();for(let y=0;y<7;y++)for(let x=0;x<7;x++)if(!open.has(x+','+y))voids.add(x+','+y);h.patch({round:3,wolf:{x:1,y:3},wolfBeforeAction:{x:1,y:3},voids,walls:new Set(),fences:new Set(),gates:new Map(),mud:new Set(),grassPatches:new Set(),guard:null,otherGuard:null,swapWarning:null,lastPounce:false,lastAction:'wait',sheep:[{id:0,real:true,x:2,y:3,stress:0,mood:'calm',safeMemory:false,comfortGrace:0,snared:0}],trapFx:{x:3,y:3,ttl:6,triggered:false}});h.render();};document.getElementById('readFlock').onclick=()=>{const s=h.state();document.getElementById('flockReceipt').textContent=JSON.stringify({round:s.round,sheep:s.sheep,trap:s.trapFx})};})();
